/**
 * Tile catalogue — built from the warehouse list (src/data/tiles.json).
 * The file is regenerated by the importer and edited by the Telegram bot,
 * so keep it plain JSON.
 * @author Erbol king
 */
import type { Collection } from './types';
import { getLook } from './looks';
import data from '@/data/tiles.json';

const KNOWN_THICKNESS = new Set(['idalgo', 'granitea']);

export const collections: Collection[] = (data.collections as unknown as Collection[]).map((c) => ({
  ...c,
  description: c.description || getLook(c.look)?.description || '',
  thickness: KNOWN_THICKNESS.has(c.brand) ? c.thickness || '10 мм' : '',
}));
